window.docContents[112].resolve({"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Dedu______o-Natural/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Dedu______o-Natural--Implica______o":{"contents":"Para introduzir P → Q, suponha P, derive Q e descarte a suposição. Para eliminá-la, aplique uma implicação a uma prova do seu antecedente, a regra de modus ponens.\n\n   [P]\n    ⋮\n    Q                   P → Q    P\n  ───────  →I          ─────────────  →E\n   P → Q                     Q\n\n\n","context":"Verificação Formal de Software\u0009Aula 1: Motivação e Lógica Proposicional\u0009Dedução Natural","header":"1.5.1. Implicação","id":"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Dedu______o-Natural/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Dedu______o-Natural--Implica______o"}});